 _makeSky(){const geo=new THREE.SphereGeometry(1100,40,24);const mat=new THREE.ShaderMaterial({side:THREE.BackSide,depthWrite:false,toneMapped:false,uniforms:{top:{value:new THREE.Color()},horizon:{value:new THREE.Color()},sun:{value:new THREE.Color()},sunDirection:{value:new THREE.Vector3(-.35,.19,-.9).normalize()},night:{value:1},time:{value:0}},vertexShader:'varying vec3 vDirection;void main(){vDirection=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.0);}',fragmentShader:`precision highp float;varying vec3 vDirection;uniform vec3 top;uniform vec3 horizon;uniform vec3 sun;uniform vec3 sunDirection;uniform float night;uniform float time;float hsh(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}float noise2(vec2 p){vec2 i=floor(p),f=fract(p);f=f*f*(3.0-2.0*f);return mix(mix(hsh(i),hsh(i+vec2(1.0,0.0)),f.x),mix(hsh(i+vec2(0.0,1.0)),hsh(i+vec2(1.0,1.0)),f.x),f.y);}float fbm(vec2 p){return noise2(p)*.55+noise2(p*2.03)*.27+noise2(p*4.11)*.13+noise2(p*8.23)*.05;}void main(){vec3 d=normalize(vDirection);float h=max(d.y,0.0);vec3 col=mix(horizon,top,pow(h,.38));float sd=dot(d,sunDirection);col+=sun*pow(max(sd,0.0),28.0)*.11;col+=sun*pow(max(sd,0.0),200.0)*.45;col=mix(col,sun*2.0,smoothstep(.99925,.99955,sd));vec2 plane=d.xz/max(.14,d.y+.12)*1.8+vec2(time*.001,0.0);float clouds=smoothstep(.51,.74,fbm(plane))*smoothstep(.03,.25,d.y)*(1.0-smoothstep(.6,.95,d.y));vec3 cloudColor=mix(vec3(.92,.85,.79),horizon*.9,night);col=mix(col,cloudColor,clouds*.42);float stars=step(.9993,hsh(floor(d.xz/max(.15,d.y)*800.0)))*smoothstep(.2,.55,d.y)*night;col+=vec3(stars*.25);gl_FragColor=vec4(col,1.0);}`});const m=new THREE.Mesh(geo,mat);m.frustumCulled=false;return m;}
