  if(this.circuit==='miami'){addStrip(-17,380,material(t.ground,{roughness:1}),-.16,80);addStrip(-27,-17,material(0xe1c6a0,{roughness:1}),-.3,12);}else addStrip(-380,380,material(this.circuit==='desert'?0xe7c39b:t.ground,{roughness:1,...(this.circuit==='desert'?terrain:{})}),-.16,80);
  addStrip(-8.6,8.6,material(t.night?0x2b2a35:0xa09a8d,{roughness:.9}),-.025);
